INSERT INTO `quest_template_locale` (`ID`,`locale`,`LogTitle`,`LogDescription`,`QuestDescription`) VALUES (1,'deDE','[The "Chow" Quest (123)aa]','[Kill Kobold Vermin, 2 of em.]','[$Tpunk;! Kill Kobold Vermin, 2 of em. NEW TEST AGAIN]'),
