(4148,'esMX','Liquidador de pétalos de sangre',NULL,NULL),
(4148,'frFR','La baguette Pétale-de-sang',NULL,NULL),
(4148,'itIT','Bloodpetal Zapper',NULL,NULL),
(4148,'koKR','붉은꽃잎 구제장치',NULL,NULL),
(4148,'ptBR','Fulminadora de Pétala Sangrenta',NULL,NULL),
(4148,'ruRU','Антикровоцветный шокер',NULL,NULL),
